# verify by exact per-id re-read
ok = 0
counts = {"changed_main":0, "reserve_used":0, "disputed":0}
for cid in IDS:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        rec = json.load(f)
    assert rec["case_id"] == cid and rec["prediction_text"] and rec["basis"]
    assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    for k in counts:
        if rec["trigger"][k]: counts[k] += 1
    ok += 1
print("written_and_verified:", ok)
print("trigger_counts:", counts)
